// Reproduces CPython's repr() of a bytes object.
// bytes: Uint8Array -> string like b'\xbc\x08...'

export function pyBytesRepr(bytes) {
  let hasSingle = false;
  let hasDouble = false;
  for (const b of bytes) {
    if (b === 0x27) hasSingle = true;
    else if (b === 0x22) hasDouble = true;
  }
  // CPython uses single quotes unless the data has a single quote and no double quote.
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quoteChar = String.fromCharCode(quote);

  let out = "b" + quoteChar;
  for (const b of bytes) {
    if (b === 0x5c) {
      out += "\\\\";
    } else if (b === quote) {
      out += "\\" + quoteChar;
    } else if (b === 0x09) {
      out += "\\t";
    } else if (b === 0x0a) {
      out += "\\n";
    } else if (b === 0x0d) {
      out += "\\r";
    } else if (b >= 0x20 && b <= 0x7e) {
      out += String.fromCharCode(b);
    } else {
      out += "\\x" + b.toString(16).padStart(2, "0");
    }
  }
  out += quoteChar;
  return out;
}

