// Minimal argparse mimic for: parser with prog 'test16_executable'
// and two required string options --key and --data.

const PROG = "test16_executable";
const USAGE = `usage: ${PROG} [-h] --key KEY --data DATA`;

function printHelp() {
  console.log(USAGE);
  console.log("");
  console.log("options:");
  console.log("  -h, --help   show this help message and exit");
  console.log("  --key KEY");
  console.log("  --data DATA");
}

function error(message) {
  console.error(USAGE);
  console.error(`${PROG}: error: ${message}`);
  process.exit(2);
}

// argv: array of strings (process.argv.slice(2)) -> { key, data }
export function parseArgs(argv) {
  let key;
  let data;
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === "-h" || arg === "--help") {
      printHelp();
      process.exit(0);
    }
    let name = null;
    let value = null;
    if (arg.startsWith("--")) {
      const eq = arg.indexOf("=");
      if (eq !== -1) {
        name = arg.slice(0, eq);
        value = arg.slice(eq + 1);
      } else {
        name = arg;
      }
    }
    if (name === "--key" || name === "--data") {
      if (value === null) {
        if (i + 1 >= argv.length) {
          error(`argument ${name}: expected one argument`);
        }
        value = argv[i + 1];
        i += 1;
      }
      if (name === "--key") key = value;
      else data = value;
    } else {
      unrecognized.push(arg);
    }
    i += 1;
  }

  if (unrecognized.length > 0) {
    error(`unrecognized arguments: ${unrecognized.join(" ")}`);
  }

  const missing = [];
  if (key === undefined) missing.push("--key");
  if (data === undefined) missing.push("--data");
  if (missing.length > 0) {
    error(`the following arguments are required: ${missing.join(", ")}`);
  }

  return { key, data };
}

