// Node.js port of test16.py (pyaes AES-ECB, per-block encrypt + print).
import { parseArgs } from "./lib/args.mjs";
import { aesEcbEncryptBlock } from "./lib/aes.mjs";
import { pyBytesRepr } from "./lib/pybytes.mjs";

function main() {
  const args = parseArgs(process.argv.slice(2));

  let key;
  try {
    key = new TextEncoder().encode(args.key);
    if (key.length !== 16 && key.length !== 24 && key.length !== 32) {
      throw new Error("Invalid key size");
    }
  } catch (err) {
    // pyaes raises ValueError -> traceback on stderr, exit code 1.
    console.error(`ValueError: ${err.message}`);
    process.exit(1);
  }

  const data = new TextEncoder().encode(args.data);

  for (let i = 0; i < data.length; i += 16) {
    const block = data.subarray(i, i + 16);
    if (block.length !== 16) {
      // pyaes ECB requires block-aligned data.
      console.error("ValueError: Data must be aligned to block boundary in ECB mode");
      process.exit(1);
    }
    const cipher = aesEcbEncryptBlock(key, block);
    console.log(pyBytesRepr(cipher));
  }
}

main();

