98	  t = s[6]; s[6] = s[14]; s[14] = t;
99	  // Row 3: shift left by 3 (right by 1)
100	  t = s[15]; s[15] = s[11]; s[11] = s[7]; s[7] = s[3]; s[3] = t;
101	}
102	
103	function mixColumns(s) {
104	  for (let c = 0; c < 4; c++) {
105	    const i = c * 4;
106	    const a0 = s[i], a1 = s[i + 1], a2 = s[i + 2], a3 = s[i + 3];
107	    s[i]     = gmul(a0, 2) ^ gmul(a1, 3) ^ a2 ^ a3;
108	    s[i + 1] = a0 ^ gmul(a1, 2) ^ gmul(a2, 3) ^ a3;
109	    s[i + 2] = a0 ^ a1 ^ gmul(a2, 2) ^ gmul(a3, 3);
110	    s[i + 3] = gmul(a0, 3) ^ a1 ^ a2 ^ gmul(a3, 2);
111	  }
112	}
113	
114	function addRoundKey(s, rk, round) {
115	  const o = round * 16;
116	  for (let i = 0; i < 16; i++) s[i] ^= rk[o + i];
117	}
118	
119	/**
120	 * Encrypt a single 16-byte block with AES in ECB mode.
121	 * @param {Uint8Array} keyBytes  - 16, 24, or 32 byte key (like pyaes).
122	 * @param {Uint8Array} blockBytes - exactly 16 bytes of plaintext.
123	 * @returns {Uint8Array} 16-byte ciphertext.
124	 */
125	export function aesEcbEncryptBlock(keyBytes, blockBytes) {
126	  const key = keyBytes instanceof Uint8Array ? keyBytes : Uint8Array.from(keyBytes);
127	  const block = blockBytes instanceof Uint8Array ? blockBytes : Uint8Array.from(blockBytes);
128	  const { roundKeys, rounds } = expandKey(key);
129	  const s = block.slice();
130	
131	  addRoundKey(s, roundKeys, 0);
132	  for (let round = 1; round < rounds; round++) {
133	    subBytes(s);
134	    shiftRows(s);
135	    mixColumns(s);
136	    addRoundKey(s, roundKeys, round);
137	  }
138	  subBytes(s);
139	  shiftRows(s);
140	  addRoundKey(s, roundKeys, rounds);
141	
142	  return s;
143	}
